function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.invest}"/></svg>`}
const nav=[['accueil','Accueil','home'],['objectifs','Objectifs','building'],['budget','Gérer son budget','coin'],['plan','Mon Plan','plan'],['investir','Investir','invest'],['apprendre','Apprendre','book'],['simulateurs','Simulateurs','calc'],['profil','Profil','user']];
let state={palette:'green',currency:'XPF',profile:{goal:'Faire grandir mon patrimoine',horizon:15,risk:7,loss:7,liquidity:'long',knowledge:'debutant',experience:'aucune',involvement:'passif',residence:'nc',safety:'non'},capital:1500000,monthly:40000,target:20000000,rate:5,years:20,done:[0,1],lessons:[],hideProfile:false};const INITIAL_STATE=structuredClone(state);if(!state.budget||!Array.isArray(state.budget.entries))state.budget={entries:[]};let filter='Tout';let current='accueil';function save(){syncActiveGoal();queueCloudSave();}function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,3200)}
// Monetary amounts stay in XPF internally; changing the display never rewrites them.
const EUR_PER_XPF=0.00838;
const moneyKeys=['capital','monthly','target'];
const goalKeys=['capital','monthly','target','years','rate'];
const goalTypes=[['home','Achat de résidence principale','home'],['car','Financement d’une voiture','invest'],['studies','Études des enfants','book'],['retirement','Préparer la retraite','leaf'],['safety','Épargne de sécurité','shield'],['travel','Voyage','globe'],['works','Travaux et rénovation','building'],['business','Création d’entreprise','invest'],['wealth','Constituer un patrimoine','coin'],['other','Autre projet','plan']];
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function activeGoal(){return state.goals?.find(g=>g.id===state.activeGoalId)}
function syncActiveGoal(){const g=activeGoal();if(g){goalKeys.filter(k=>k!=='capital').forEach(k=>g[k]=state[k]);g.capital=latestObservation(g).value;state.capital=g.capital;}}
function loadActiveGoal(){const g=activeGoal();if(g)goalKeys.forEach(k=>state[k]=g[k]);}
// Retain the user's existing project and all previously entered amounts.
if(!Array.isArray(state.goals)){state.goals=[{id:'initial-goal',name:'Mon premier objectif',type:'wealth',...Object.fromEntries(goalKeys.map(k=>[k,state[k]]))}];state.activeGoalId='initial-goal';}
for(const g of state.goals){g.startDateConfirmed=typeof g.startDateConfirmed==='boolean'?g.startDateConfirmed:Boolean(g.startDate);g.startDate=g.startDate||todayISO();g.initialCapital=Number.isFinite(g.initialCapital)?g.initialCapital:g.capital;g.records=Array.isArray(g.records)?g.records:[];g.capital=latestObservation(g).value;}
if(!activeGoal())state.activeGoalId=state.goals[0]?.id||null;
loadActiveGoal();
function selectGoal(id){if(!state.goals.some(g=>g.id===id))return;syncActiveGoal();state.activeGoalId=id;loadActiveGoal();save();render();}
function goalType(g){return goalTypes.find(t=>t[0]===g.type)||goalTypes.at(-1)}
function goalAchieved(g){return Number.isFinite(g.capital)&&Number.isFinite(g.target)&&g.target>0&&g.capital>=g.target;}
function goalNameWithStatus(g){return `${escapeHTML(g.name)}${goalAchieved(g)?'<span class="goal-achieved-check" role="img" aria-label="Objectif atteint">✓</span>':''}`;}
function fundedPercent(g){return Math.min(100,Math.max(0,g.capital/g.target*100))}
function goalSelector(){return `<label class="goal-selector"><span>Objectif sélectionné</span><select data-goal-selector aria-label="Choisir un objectif">${state.goals.map(g=>`<option value="${escapeHTML(g.id)}" ${g.id===state.activeGoalId?'selected':''}>${goalAchieved(g)?'✓ ':''}${escapeHTML(g.name)}</option>`).join('')}</select></label>`}
function goalProgress(g){const p=fundedPercent(g);return `<div class="goal-progress-text"><span>${amount(g.capital)} ${unit()} déjà épargnés</span><b>${p.toLocaleString('fr-FR',{maximumFractionDigits:1})} %</b></div><progress class="goal-progress" value="${p}" max="100" aria-label="Progression de l’épargne : ${p.toFixed(1)} %"></progress>`}
function goalCreateButton(){return '<button class="btn create-goal" data-action="newgoal"><span aria-hidden="true">＋</span> Créer un nouvel objectif</button>'}

function unit(){return state.currency==='EUR'?'€':'XPF'}
function displayValue(xpf){return state.currency==='EUR'?xpf*EUR_PER_XPF:xpf}
function toXPF(value){return state.currency==='EUR'?Number(value)/EUR_PER_XPF:Number(value)}
function amount(xpf){return displayValue(xpf).toLocaleString('de-DE',{minimumFractionDigits:state.currency==='EUR'?2:0,maximumFractionDigits:state.currency==='EUR'?2:0})}
function inputValue(xpf){return amount(xpf)}
function moneyInput(name,xpf,readonly=false){
 const maximum=displayValue(['monthly','investment'].includes(name)?100000000:100000000000),minimum=name==='target'?(state.currency==='EUR'?.01:1):0;
 const pattern=state.currency==='EUR'?'(?:[0-9]+|[0-9]{1,3}(?:[.][0-9]{3})+)(?:,[0-9]{1,2})?':'(?:[0-9]+|[0-9]{1,3}(?:[.][0-9]{3})+)';
 return `<input name="${name}" type="text" inputmode="${state.currency==='EUR'?'decimal':'numeric'}" value="${inputValue(xpf)}" data-money data-xpf="${xpf}" data-displayed="${inputValue(xpf)}" data-minimum="${minimum}" data-maximum="${maximum}" pattern="${pattern}" ${readonly?'readonly aria-readonly="true"':''} required>`;
}
function parseMoneyText(value){const normalized=String(value).replace(/[\s\u00a0\u202f]/g,'');const pattern=state.currency==='EUR'?/^(?:[0-9]+|[0-9]{1,3}(?:\.[0-9]{3})+)(?:,[0-9]{1,2})?$/:/^(?:[0-9]+|[0-9]{1,3}(?:\.[0-9]{3})+)$/;return pattern.test(normalized)?Number(normalized.replaceAll('.','').replace(',','.')):NaN}
function readMoneyInput(input){const value=parseMoneyText(input.value);return value===parseMoneyText(input.dataset.displayed)?Number(input.dataset.xpf):toXPF(value)}
function validateMoneyInput(input){const value=parseMoneyText(input.value),valid=Number.isFinite(value)&&value>=Number(input.dataset.minimum)&&value<=Number(input.dataset.maximum);input.setCustomValidity(valid?'':`Saisis un montant valide en ${unit()} : points pour les milliers${state.currency==='EUR'?', virgule pour les centimes':''}.`);return valid;}
function validateMoneyFields(form){form.querySelectorAll('[data-money]').forEach(validateMoneyInput);return form.checkValidity();}
function simValues(form){return Object.fromEntries([...form.elements].filter(el=>el.name).map(el=>[el.name,moneyKeys.includes(el.name)?readMoneyInput(el):Number(el.value)]))}
function lessonText(text){return text.replace(/([0-9]+(?: [0-9]{3})*) XPF/g,(_,n)=>`${amount(Number(n.replaceAll(' ','')))} ${unit()}`)}
function changeCurrency(nextCurrency){
 if(!['XPF','EUR'].includes(nextCurrency)||state.currency===nextCurrency)return;
 const form=$('#simform')||$('#profileform');
 if(form&&!form.checkValidity()){$('#currency-select').value=state.currency;form.reportValidity();toast('Vérifie les champs avant de changer de devise.');return;}
 const snapshot=form?Object.fromEntries([...form.elements].filter(el=>el.name).map(el=>[el.name,moneyKeys.includes(el.name)?readMoneyInput(el):el.value])):null;
 const formId=form?.id;
 state.currency=nextCurrency;save();render();
 if(snapshot){const restored=$('#'+formId);Object.entries(snapshot).forEach(([key,value])=>{const input=restored.elements.namedItem(key);if(moneyKeys.includes(key)){input.value=inputValue(value);input.dataset.xpf=value;input.dataset.displayed=input.value;}else{input.value=value;if(input.type==='range')input.parentElement.querySelector('output').textContent=value;}});if(formId==='simform')$('#simresult').innerHTML=simResult(simValues(restored));}
 toast(`Montants affichés en ${nextCurrency==='EUR'?'euros':'francs CFP'}.`);
}
