const legacyPlanMap={0:'goal-purpose',1:'profile-questionnaire',2:'prep-reserve',3:'asset-etf',4:'envelope-compare',5:'envelope-broker',6:'asset-allocation',7:'envelope-order',8:'prep-routine'};
const planItemIds=planStages.flatMap(stage=>stage.items.map(item=>item[0]));
if(!Array.isArray(state.planDone))state.planDone=[...new Set((state.done||[]).map(id=>legacyPlanMap[id]).filter(Boolean))];
state.planDone=state.planDone.filter(id=>planItemIds.includes(id));
function stageCount(stage){return stage.items.filter(item=>state.planDone.includes(item[0])).length}
function completedStages(){return planStages.filter(stage=>stageCount(stage)===stage.items.length).length}
function markPlanItem(id,checked=true){if(!planItemIds.includes(id))return;state.planDone=checked?[...new Set([...state.planDone,id])]:state.planDone.filter(item=>item!==id);const legacy=Object.keys(legacyPlanMap).find(key=>legacyPlanMap[key]===id);if(legacy!==undefined)state.done=checked?[...new Set([...state.done,Number(legacy)])]:state.done.filter(key=>key!==Number(legacy));if(id==='prep-reserve')state.profile.safety=checked?'oui':'non';}
function openPlanResource(destination){if(destination.startsWith('legacy:')){openStep(Number(destination.split(':')[1]));return;}if(destination.startsWith('lesson:')){openLesson(Number(destination.split(':')[1]));return;}if(destination==='enveloppes'){filter='Les enveloppes';go('investir');return;}go(destination);}
const assets=[{name:'ETF Monde',sub:'Actions · Diversification internationale',icon:'globe',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:7,horizon:10,complexity:1,liquid:1,div:1,desc:'Un fonds coté qui cherche à suivre un indice d’actions de plusieurs pays. Un seul achat donne accès à un ensemble d’entreprises.',works:'Le fonds suit un indice. Sa valeur monte ou baisse avec les marchés, après frais. « Monde » ne signifie pas tous les pays : la couverture dépend de l’indice choisi.',pros:'Diversification et gestion simple ; frais souvent modérés.',cons:'Perte en capital possible ; concentration possible sur les États-Unis et exposition aux devises.',envelopes:'CTO ; PEA pour certains ETF éligibles ; assurance-vie ou PER selon le contrat.',vol:'Élevée',difficulty:'Accessible'}, {name:'ETF S&P 500',sub:'Actions · Grandes entreprises américaines',icon:'invest',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:7,horizon:10,complexity:1,liquid:1,div:.75,desc:'Un fonds qui suit un indice de grandes entreprises cotées aux États-Unis.',works:'Sa performance dépend des actions américaines et, selon le produit, du taux de change.',pros:'Large panier d’entreprises américaines ; fonctionnement simple.',cons:'Concentration sur un seul marché ; risques de marché et de change.',envelopes:'CTO ; certains ETF éligibles au PEA ; selon les contrats d’assurance-vie ou PER.',vol:'Élevée',difficulty:'Accessible'}, {name:'Obligations',sub:'Revenus · Financer des États et entreprises',icon:'shield',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:4,horizon:5,complexity:2,liquid:.8,div:.7,desc:'Une obligation est une dette : tu prêtes à un État ou une entreprise, qui s’engage à rembourser selon des conditions définies.',works:'Elle peut verser des intérêts. Son prix varie avec les taux et la solidité de l’émetteur.',pros:'Revenus possibles et diversification du portefeuille.',cons:'Défaut de l’émetteur, variation des taux et érosion par l’inflation. Certaines obligations sont très risquées.',envelopes:'CTO ; fonds obligataires dans certains contrats d’assurance-vie et PER.',vol:'Variable',difficulty:'Intermédiaire'}, {name:'Immobilier',sub:'Patrimoine · Actifs tangibles',icon:'building',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:6,horizon:10,complexity:2,liquid:.1,div:.4,desc:'Investir dans un bien ou un véhicule collectif exposé à l’immobilier, pour espérer des revenus ou une valorisation.',works:'Le revenu dépend des loyers encaissés après charges. Un fonds immobilier a ses propres frais et conditions de sortie.',pros:'Actif tangible ; revenus locatifs possibles.',cons:'Vacance, impayés, travaux, frais et revente parfois lente. Le crédit amplifie les risques.',envelopes:'Détention directe ; SCPI en direct ou dans certains contrats d’assurance-vie.',vol:'Peu visible au quotidien',difficulty:'Intermédiaire'}, {name:'Actions individuelles',sub:'Actions · Choisir ses entreprises',icon:'invest',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:8,horizon:10,complexity:3,liquid:1,div:.1,desc:'Une action représente une petite part d’une entreprise.',works:'Son cours évolue selon les perspectives de l’entreprise et le marché. Le dividende n’est pas garanti.',pros:'Choix direct des entreprises ; potentiel de croissance.',cons:'Risque de concentration et de perte totale sur une entreprise ; analyse nécessaire.',envelopes:'CTO ; PEA pour les titres éligibles.',vol:'Élevée',difficulty:'Avancé'}, {name:'Bitcoin',sub:'Cryptoactifs · Forte volatilité',icon:'coin',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:10,horizon:10,complexity:3,liquid:.8,div:0,desc:'Un cryptoactif échangé sur un réseau décentralisé, sans garantie de valeur.',works:'Son prix dépend de l’offre et de la demande. La conservation repose sur des clés ou un prestataire.',pros:'Transfert sur un réseau ouvert ; exposition distincte des actifs traditionnels.',cons:'Très fortes variations, perte totale possible, piratage et erreurs de conservation.',envelopes:'Compte auprès d’un prestataire ou portefeuille de cryptoactifs ; ne pas confondre avec le PEA.',vol:'Très élevée',difficulty:'Avancé'}, {name:'Trading à effet de levier',sub:'Produits complexes · Risque extrême',icon:'invest',bg:'var(--tone-edf3f0)',color:'var(--tone-17634b)',risk:10,horizon:1,complexity:5,liquid:.8,div:0,desc:'L’effet de levier multiplie ton exposition aux mouvements d’un marché.',works:'Il amplifie les gains comme les pertes ; les coûts et mécanismes dépendent du produit.',pros:'Exposition amplifiée, réservée à des usages et connaissances spécifiques.',cons:'Perte très rapide du capital, liquidation et parfois pertes supérieures à la mise selon le produit.',envelopes:'Comptes et produits spécialisés, selon l’intermédiaire et la réglementation.',vol:'Extrême',difficulty:'Expert'}];
function scores(a){const p=state.profile,r=Math.min(+p.risk,+p.loss);const horizon=Math.min(100,+p.horizon/a.horizon*100);const risk=Math.max(0,100-Math.max(0,a.risk-r)*23-Math.max(0,r-a.risk)*4);const complexity=Math.max(0,100-(a.complexity-1)*(p.knowledge==='avance'?8:p.knowledge==='intermediaire'?17:25)-(a.complexity>=3&&p.experience==='aucune'?10:0)-(a.complexity>=3&&p.involvement==='passif'?10:0));const liquidity=p.liquidity==='court'?a.liquid*100:100;const diversification=40+a.div*60;let total=Math.round(.3*risk+.25*horizon+.2*complexity+.15*diversification+.1*liquidity);if(a.complexity===5)total=Math.min(total,18);if(a.name==='Bitcoin'&&p.knowledge==='debutant')total=Math.min(total,37);if(p.liquidity==='court'||p.horizon<3)total=Math.min(total,a.risk>=7?35:60);return {total,items:[['Risque supportable',risk,30],['Horizon',horizon,25],['Complexité',complexity,20],['Diversification',diversification,15],['Liquidité',liquidity,10]]}}
function profileName(){const r=Math.min(state.profile.risk,state.profile.loss);return `${r<=3?'Prudent':r<=6?'Équilibré':'Dynamique'} ${state.profile.horizon>=10?'long terme':state.profile.horizon>=5?'moyen terme':'court terme'}`}
function progress(){return Math.round(state.planDone.length/planItemIds.length*100)}function next(){return planStages.findIndex(stage=>stageCount(stage)<stage.items.length)}function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function projection(c,m,r,y){const rate=Math.pow(1+r/100,1/12)-1;return Array.from({length:y+1},(_,i)=>({year:i,paid:c+m*12*i,value:rate===0?c+m*12*i:c*Math.pow(1+rate,i*12)+m*(Math.pow(1+rate,i*12)-1)/rate}))}
function monthlyProjection(c,m,r,y){
 const rate=Math.pow(1+r/100,1/12)-1;
 let value=c;const data=[{month:0,year:0,value,paid:c}];
 for(let month=1;month<=y*12;month++){value=value*(1+rate)+m;data.push({month,year:month/12,value,paid:c+m*month});}
 return data;
}
function goalMoment(c,m,r,y,target){return monthlyProjection(c,m,r,y).find(p=>p.value>=target)||null}
function durationLabel(month){if(month===0)return 'dès le départ';const years=Math.floor(month/12),months=month%12;return [years?`${years} an${years>1?'s':''}`:'',months?`${months} mois`:''].filter(Boolean).join(' et ')}
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function isISODate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value}
function dateNumber(date){return Date.parse(date+'T00:00:00Z')}
function addMonths(date,months){const d=new Date(date+'T00:00:00Z'),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+months);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10)}
function dateLabel(date){return new Date(date+'T00:00:00Z').toLocaleDateString('fr-FR',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'})}
function relativeDate(date,asOf=todayISO()){
 if(date===asOf)return 'aujourd’hui';
 const future=date>asOf,from=future?asOf:date,to=future?date:asOf;
 const a=new Date(from+'T00:00:00Z'),b=new Date(to+'T00:00:00Z');
 let months=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();
 if(addMonths(from,months)>to)months--;
 const years=Math.floor(months/12),remaining=months%12;
 const days=Math.round((dateNumber(to)-dateNumber(from))/86400000);
 const duration=months===0?days+' jour'+(days>1?'s':''):[years?years+' an'+(years>1?'s':''):'',remaining?remaining+' mois':''].filter(Boolean).join(' et ');
 return (future?'dans ':'il y a ')+duration;
}
function shortDate(date){return new Date(date+'T00:00:00Z').toLocaleDateString('fr-FR',{timeZone:'UTC',month:'short',year:'numeric'})}
function sortedRecords(g){return [...(g.records||[])].sort((a,b)=>a.date.localeCompare(b.date))}
function latestObservation(g){return sortedRecords(g).at(-1)||{date:g.startDate,value:g.initialCapital??g.capital,investment:0}}
function goalTimeline(g,asOf=todayISO()){
 const records=sortedRecords(g);let paid=g.initialCapital;
 const actual=[{date:g.startDate,value:g.initialCapital,paid,investment:0,actual:true}];
 for(const entry of records){paid+=entry.investment;actual.push({...entry,paid,actual:true});}
 const last=actual.at(-1),deadline=addMonths(g.startDate,g.years*12),anchorDate=asOf>last.date?asOf:last.date;
 const forecast=[];let value=last.value;const rate=Math.pow(1+g.rate/100,1/12)-1;
 if(anchorDate<deadline){forecast.push({date:anchorDate,value,paid,actual:false});let month=1;
  while(addMonths(anchorDate,month)<=deadline){value=value*(1+rate)+g.monthly;paid+=g.monthly;forecast.push({date:addMonths(anchorDate,month),value,paid,actual:false});month++;}
  const previous=forecast.at(-1);if(previous.date<deadline){const next=addMonths(anchorDate,month),fraction=(dateNumber(deadline)-dateNumber(previous.date))/(dateNumber(next)-dateNumber(previous.date));value*=Math.pow(1+rate,fraction);forecast.push({date:deadline,value,paid,actual:false});}
 }
 const hit=actual.find(p=>p.value>=g.target)||forecast.find(p=>p.value>=g.target)||null;
 const end=forecast.at(-1)||last;
 return {actual,forecast,last,end,hit,deadline,anchorDate,expired:anchorDate>=deadline,paidActual:last.paid,startDate:g.startDate,endDate:[deadline,last.date,asOf].sort().at(-1)};
}
let chartSequence=0;
function niceChartAxis(high){const raw=Math.max(displayValue(high),1),rough=raw/4,power=Math.pow(10,Math.floor(Math.log10(rough))),step=[1,2,5,10].map(n=>n*power).find(n=>n>=rough)||10*power;const ceiling=Math.ceil(raw/step)*step;return {max:toXPF(ceiling),ticks:Array.from({length:Math.round(ceiling/step)+1},(_,i)=>toXPF(i*step))}}
function goalAmount(g){return `<div class="amount goal-amount"><span class="current-goal-amount">${amount(g.capital)}</span><span class="goal-amount-target"> / ${amount(g.target)}</span><small>${unit()}</small></div>`}
function chart(c=state.capital,m=state.monthly,r=state.rate,y=state.years,target=state.target){
 const g={...activeGoal(),monthly:m,rate:r,years:y,target};const timeline=goalTimeline(g),{actual,forecast,hit}=timeline;
 const all=[...actual,...forecast],axis=niceChartAxis(Math.max(target,...all.map(d=>Math.max(d.value,d.paid)),1)*1.08),max=axis.max;
 const left=68,right=576,top=44,bottom=205,start=dateNumber(g.startDate),finish=Math.max(start+86400000,dateNumber(timeline.endDate));
 const x=date=>left+(dateNumber(date)-start)/(finish-start)*(right-left),yp=value=>bottom-value/max*(bottom-top);
 const path=(data,key)=>data.map((p,i)=>`${i?'L':'M'}${x(p.date).toFixed(2)},${yp(p[key]).toFixed(2)}`).join(' ');
 const shownMax=displayValue(max),scale=shownMax>=1000000?1000000:shownMax>=1000?1000:1,suffix=scale===1000000?' M':scale===1000?' k':'';
 const tick=value=>(displayValue(value)/scale).toLocaleString('de-DE',{maximumFractionDigits:1})+suffix;
 const reached=timeline.last.value>=target;
 const label=hit?dateLabel(hit.date):'';
 const labelWidth=110,labelX=hit?Math.max(left,Math.min(x(hit.date)-labelWidth/2,right-labelWidth)):0,labelY=hit?Math.max(8,yp(hit.value)-36):0;
 const marker=hit?`<g class="goal-marker ${reached?'goal-marker-complete':''}"><title>${label} (${relativeDate(hit.date)}) : ${amount(hit.value)} ${unit()}</title><line x1="${x(hit.date)}" y1="${yp(hit.value)}" x2="${x(hit.date)}" y2="${bottom}" stroke="#f97316" stroke-opacity=".55" stroke-dasharray="4 5"/><circle cx="${x(hit.date)}" cy="${yp(hit.value)}" r="6" fill="#f97316" fill-opacity=".14"/><circle cx="${x(hit.date)}" cy="${yp(hit.value)}" r="3.25" fill="#f97316" stroke="white" stroke-width="1.5"/><rect x="${labelX}" y="${labelY}" width="${labelWidth}" height="27" rx="4" fill="#fff3e8" stroke="#fed7aa" stroke-width=".5"/><text x="${labelX+labelWidth/2}" y="${labelY+10}" text-anchor="middle" class="goal-label">${label}</text><text x="${labelX+labelWidth/2}" y="${labelY+21}" text-anchor="middle" class="goal-relative">(${relativeDate(hit.date)})</text></g>`:'';
 const nowDate=todayISO(),nowValue=timeline.last.value;
 const nowMarker=`<g class="current-position-marker"><title>Aujourd’hui : ${amount(nowValue)} ${unit()} · dernière valeur renseignée le ${dateLabel(timeline.last.date)}</title><line x1="${x(nowDate)}" y1="${yp(nowValue)}" x2="${x(nowDate)}" y2="${bottom}" stroke="#b99712" stroke-opacity=".65" stroke-dasharray="2 4"/><circle cx="${x(nowDate)}" cy="${yp(nowValue)}" r="6" fill="#facc15" fill-opacity=".2"/><circle cx="${x(nowDate)}" cy="${yp(nowValue)}" r="3.25" fill="#facc15" stroke="#806700" stroke-width="1.2"/></g>`;
 const gap=timeline.last.date<nowDate?`<path d="M${x(timeline.last.date)},${yp(nowValue)} L${x(nowDate)},${yp(nowValue)}" fill="none" stroke="#8b9a91" stroke-width="1.5" stroke-dasharray="2 5"><title>Dernière valeur connue reportée à aujourd’hui ; aucune performance estimée sur la période sans relevé.</title></path>`:'';
 const chartId='chart-readout-'+(++chartSequence);const points=[...all.filter(p=>p.date!==nowDate),{date:nowDate,value:nowValue,actual:timeline.last.date===nowDate,current:true,observedDate:timeline.last.date}].sort((a,b)=>a.date.localeCompare(b.date)).map(p=>({date:p.date,value:p.value,actual:p.actual,current:!!p.current,observedDate:p.observedDate,x:x(p.date),y:yp(p.value)}));
 return `<div class="interactive-chart" tabindex="0" role="group" aria-label="Explorer le graphique : utilise les flèches gauche et droite pour parcourir les dates." aria-describedby="${chartId}" data-chart-points="${escapeHTML(JSON.stringify(points))}"><svg viewBox="0 0 600 265" class="chart" role="img" aria-label="${g.startDateConfirmed?'Historique réel depuis le '+dateLabel(g.startDate):'Date de départ à préciser'} et projection jusqu’au ${dateLabel(timeline.deadline)}, en ${unit()}. ${hit?label:'Objectif non atteint sur cette durée'}."><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--tone-0b6047)" stop-opacity=".17"/><stop offset="1" stop-color="var(--tone-0b6047)" stop-opacity=".01"/></linearGradient></defs><text x="0" y="21" class="axis-unit">${unit()}</text>${axis.ticks.map(v=>{return `<line x1="${left}" y1="${yp(v)}" x2="${right}" y2="${yp(v)}" stroke="var(--tone-e8eceb)" stroke-dasharray="3 5"/><text x="0" y="${yp(v)+4}">${tick(v)}</text>`}).join('')}<line x1="${left}" y1="${yp(target)}" x2="${right}" y2="${yp(target)}" stroke="var(--tone-a5b5af)" stroke-dasharray="5 6"/>${forecast.length?`<path d="${path(forecast,'value')} L${x(forecast.at(-1).date)},${bottom} L${x(forecast[0].date)},${bottom}Z" fill="url(#area)"/>`:''}<path d="${path(actual,'paid')}" fill="none" stroke="#aeb9b5" stroke-width="1.5"/>${forecast.length?`<path d="${path(forecast,'paid')}" fill="none" stroke="#aeb9b5" stroke-width="1.5" stroke-dasharray="3 4"/>`:''}${gap}<path class="actual-history-line" d="${path(actual,'value')}" fill="none" stroke="var(--tone-07503a)" stroke-width="3"/>${actual.map(p=>`<circle cx="${x(p.date)}" cy="${yp(p.value)}" r="2.8" fill="var(--tone-07503a)" stroke="white" stroke-width="1"><title>${dateLabel(p.date)} : ${amount(p.value)} ${unit()} · versement ${amount(p.investment)} ${unit()}</title></circle>`).join('')}${forecast.length?`<path class="future-projection-line" d="${path(forecast,'value')}" fill="none" stroke="var(--tone-348a62)" stroke-width="2.5" stroke-dasharray="6 5"/>`:''}${nowMarker}${marker}${[0,.25,.5,.75,1].map(t=>{const date=new Date(start+t*(finish-start)).toISOString().slice(0,10);return `<text x="${left+t*(right-left)}" y="233" text-anchor="${t===0?'start':t===1?'end':'middle'}">${shortDate(date)}</text><text class="axis-relative" x="${left+t*(right-left)}" y="249" text-anchor="${t===0?'start':t===1?'end':'middle'}">(${relativeDate(date)})</text>`}).join('')}<g class="chart-hover-marker" style="display:none" aria-hidden="true"><line class="chart-hover-guide" y1="40" y2="205"/><circle class="chart-hover-halo" r="7"/><circle class="chart-hover-dot" r="3.5"/></g></svg><div class="chart-readout" id="${chartId}" role="tooltip" hidden><span class="chart-readout-date"></span><small class="chart-readout-relative"></small><strong class="chart-readout-value"></strong><span class="chart-readout-kind"></span></div></div><div class="legend"><span class="actual-legend">Valeurs renseignées</span><span class="current-legend">Aujourd’hui · dernière valeur renseignée</span><span class="forecast-legend">Projection · ${r} % / an</span><span class="paid-legend">Capital de départ + versements</span>${hit?`<span class="goal-legend ${reached?'goal-legend-complete':''}">Objectif atteint le ${dateLabel(hit.date)}${hit.actual?'':' (projection)'}</span>`:''}</div>`;
}
function assetRow(a){const s=scores(a).total;return `<button class="investment" data-asset="${assets.indexOf(a)}"><span class="asset-icon" style="background:${a.bg};color:${a.color}">${icon(a.icon)}</span><span class="asset-title"><b>${a.name}</b><small>${a.sub}</small></span><span class="scorebar"><span style="width:${s}%;background:${s<45?'#99a3a0':s<70?'var(--tone-5e8b7c)':'var(--tone-17634b)'}"></span></span><span class="score" style="color:${s<45?'#69746f':''}">${s}<small> /100</small></span><span class="chevron">›</span></button>`}
function dashboardGoalChoices(){return `<section class="card dashboard-goal-choices" aria-label="Tous mes objectifs"><div class="cardtop"><h2>Mes objectifs</h2><span class="pill">${state.goals.length} projet${state.goals.length>1?'s':''}</span></div><div class="dashboard-goal-list" role="group" aria-label="Choisir l’objectif affiché à gauche">${state.goals.map(g=>{const percentage=fundedPercent(g).toLocaleString('fr-FR',{maximumFractionDigits:1});return `<button type="button" class="goal-item ${goalAchieved(g)?'goal-achieved':''} ${g.id===state.activeGoalId?'selected':''}" data-goal-id="${escapeHTML(g.id)}" aria-pressed="${g.id===state.activeGoalId}" aria-controls="dashboard-goal-detail"><span class="asset-icon">${icon(goalType(g)[2])}</span><span class="goal-item-content"><b>${goalNameWithStatus(g)}</b><span>${amount(g.target)} ${unit()}</span><progress class="goal-progress" value="${fundedPercent(g)}" max="100" aria-label="${percentage} % atteint"></progress><small>${goalAchieved(g)?'Objectif atteint · ':''}${percentage} % atteint · ${amount(g.capital)} ${unit()} épargnés</small></span>${g.id===state.activeGoalId?'<span class="selected-goal-check" aria-hidden="true">✓</span>':''}</button>`}).join('')}</div><div class="dashboard-create-goal">${goalCreateButton()}</div></section>`}
function dashboard(){const p=state.profile,n=next();return heading('Bonjour '+escapeHTML(cloud.space?.name||'')+' <span class="wave">☀</span>','Chaque petit pas te rapproche de tes grands projets.',`<button class="light" data-action="customize">${icon('settings')} Personnaliser</button>`)+`<section class="welcome"><div><div class="eyebrow">TON AVENIR COMMENCE ICI</div><h2>De zéro à ton premier investissement.</h2><p>Comprendre, choisir, avancer. On t’accompagne à chaque étape.</p></div><button class="btn" data-go="plan">Continuer mon parcours ${icon('arrow')}</button></section><div class="dashboard-grid dashboard-overview"><section class="card dashboard-goal-detail" id="dashboard-goal-detail" aria-label="Objectif sélectionné"><div class="cardtop"><h2>${escapeHTML(activeGoal().name)}</h2><button class="textbutton" data-action="editgoal">Modifier cet objectif</button></div><div class="goal-head">${goalAmount(activeGoal())}<span class="pill">${escapeHTML(goalType(activeGoal())[1])}</span></div><div class="metric-row"><div><small>Prévu chaque mois</small><b>${amount(state.monthly)} ${unit()}</b></div><div><small>Horizon total depuis le départ</small><b>${state.years} ans</b></div></div>${goalProgress(activeGoal())}${chart()}${historyPanel(activeGoal())}${goalInfo()}</section>${dashboardGoalChoices()}${dashboardBudget()}<section class="card"><div class="cardtop"><h2>Des pistes pour ton profil</h2><button class="textbutton" data-go="investir">Tout explorer <span>↗</span></button></div><div class="invest-list">${[assets[0],assets[2],assets[3],assets[5]].map(assetRow).join('')}</div><p class="card-note">Compatibilité pédagogique, pas une recommandation d’achat.</p></section>${state.hideProfile?'':`<section class="card profile"><div class="cardtop"><h2>Mon profil investisseur</h2><button class="textbutton" data-go="profil" aria-label="Modifier mon profil">↗</button></div><div class="profile-badge">${icon('leaf')}</div><h3>${profileName().replace('long terme','<br>long terme')}</h3><span class="level">${p.knowledge==='debutant'?'DÉBUTANT':p.knowledge.toUpperCase()} · EN PLEINE PROGRESSION</span><div class="profile-data"><span>Tolérance au risque</span><b>${p.risk} <span style="font-weight:400">/ 10</span></b></div><div class="riskbar">${Array.from({length:10},(_,i)=>`<span class="${i<p.risk?'on':''}"></span>`).join('')}</div><div class="profile-meta"><span>Horizon d’investissement</span><b>${p.horizon} ans</b></div></section>`}<section class="card"><div class="cardtop"><h2>Mon parcours</h2><button class="textbutton" data-go="plan">Voir mon plan ↗</button></div><div class="journey-top"><div class="ring" style="--progress:${progress()}%"><span>${progress()}%</span></div><div><b>Tu es sur la bonne voie.</b><p>${completedStages()} grandes étapes sur 5 terminées</p></div></div>${planStages.slice(0,2).map(stage=>`<div class="step-mini"><span class="check-circle">${stageCount(stage)===stage.items.length?'✓':'○'}</span>${stage.title}</div>`).join('')}<div class="nextstep"><span class="check-circle">${n===-1?'✓':n+1}</span><span><small style="display:block;font-size:9px;color:var(--tone-919e7c);margin-bottom:5px">${n===-1?'BRAVO !':'PROCHAINE ÉTAPE'}</small>${n===-1?'Ton parcours est complété':planStages[n].title}</span><button class="textbutton" data-go="plan" aria-label="Continuer mon parcours">→</button></div></section><section class="card learn-strip"><div class="lesson-art">${icon('book')}</div><div><span class="tiny-label">UN PEU PLUS CLAIR, EN 3 MINUTES</span><h3>Les intérêts composés : le temps est ton allié.</h3><p>Découvre comment tes gains peuvent à leur tour générer des gains.</p></div><span class="duration">◷ 3 min · Les bases</span><button class="btn" data-lesson="1">Découvrir la leçon →</button></section></div><div class="foot-tip">${icon('shield').replace('class="icon"','class="icon" style="width:13px;height:13px;vertical-align:middle;margin-right:5px"')} Pas besoin de tout savoir pour commencer à apprendre.</div>`}
function plan(){const nextStage=next();return heading('Mon plan, un pas à la fois.','Cinq grandes étapes pour comprendre, préparer et commencer à investir.')+`<div class="investment-plan"><section class="card plan-overview"><div class="ring" style="--progress:${progress()}%"><span>${progress()}%</span></div><div><h2>Mon parcours pour débuter</h2><p>${completedStages()} / 5 grandes étapes terminées · ${state.planDone.length} / ${planItemIds.length} actions validées</p></div><span class="pill">À ton rythme</span></section><div class="plan-stages">${planStages.map((stage,i)=>{const count=stageCount(stage),complete=count===stage.items.length;return `<details class="card plan-stage ${complete?'stage-complete':''}" id="plan-stage-${i}" ${i===nextStage?'open':''}><summary><span class="plan-stage-number">${complete?'✓':i+1}</span><span class="plan-stage-title"><small>ÉTAPE ${i+1}</small><strong>${stage.title}</strong></span><span class="plan-stage-progress">${count} / ${stage.items.length}<span>${complete?'Terminée':'actions'}</span></span><span class="plan-stage-chevron" aria-hidden="true">⌄</span></summary><div class="plan-stage-body"><p class="plan-stage-intro">${stage.intro}</p>${stage.items.map((item,j)=>`<div class="plan-task ${state.planDone.includes(item[0])?'task-done':''}"><input type="checkbox" data-plan-item="${item[0]}" aria-label="Valider : ${item[1]}" ${state.planDone.includes(item[0])?'checked':''}><details class="plan-substep" id="plan-substep-${item[0]}"><summary><span><small>${i+1}.${j+1}</small> ${item[1]}</span><span aria-hidden="true">＋</span></summary><div><p>${item[2]}</p>${item[3]?`<button class="textbutton" data-plan-resource="${item[3]}">${item[4]} →</button>`:''}</div></details></div>`).join('')}</div></details>`}).join('')}</div></div>`}
function invest(){return heading('Trouve les pistes qui te correspondent.','Comprends les investissements avant de faire tes propres choix.')+`<div class="filters">${['Tout','Actions & ETF','Revenus & immobilier','Crypto & trading','Les enveloppes'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>${filter==='Les enveloppes'?envelopes():`<div class="notice" style="margin:0 0 23px">Profil : <b>${profileName()}</b> · Scores indicatifs issus de règles pédagogiques. Ils ne mesurent ni un rendement attendu ni une probabilité de succès. <button class="textbutton" data-go="profil">Ajuster mon profil →</button></div><div class="viewgrid">${assets.filter(a=>filter==='Tout'||filter==='Actions & ETF'&&[0,1,4].includes(assets.indexOf(a))||filter==='Revenus & immobilier'&&[2,3].includes(assets.indexOf(a))||filter==='Crypto & trading'&&[5,6].includes(assets.indexOf(a))).sort((a,b)=>scores(b).total-scores(a).total).map(a=>`<section class="card"><div class="cardtop"><span class="asset-icon" style="background:${a.bg};color:${a.color}">${icon(a.icon)}</span><span class="score">${scores(a).total}<small> /100</small></span></div><h3>${a.name}</h3><p>${a.desc}</p><div class="overline">Risque : ${a.vol} · ${a.difficulty}</div><button class="textbutton" style="margin-top:22px" data-asset="${assets.indexOf(a)}">Comprendre et voir mon score →</button></section>`).join('')}</div><p class="source">Repères pédagogiques : <a href="https://www.amf-france.org/fr/espace-epargnants/savoir-bien-investir/cadrer-son-projet/risques-et-rendements-des-placements" target="_blank" rel="noopener">AMF — Rendements et risques des placements</a>. Un ETF actions reste risqué, même diversifié.</p>`}`}
const envs=[['PEA','Une enveloppe pour certains titres et fonds éligibles.','Son ouverture dépend notamment de la résidence fiscale. Le choix de titres est encadré. Vérifie ton éligibilité avant toute démarche.'],['CTO','Un compte pour détenir des titres financiers.','Actions, obligations et fonds selon le courtier. Frais et fiscalité dépendent de ta situation et du pays.'],['Assurance-vie','Un contrat proposant différents supports d’épargne.','Fonds en euros et unités de compte selon le contrat. Les unités de compte peuvent perdre de la valeur.'],['PER','Une enveloppe orientée vers la retraite.','L’épargne est en principe bloquée jusqu’à la retraite, avec des cas de sortie anticipée prévus par les règles applicables.'],['Livrets','Une épargne bancaire pour conserver de l’argent disponible.','Vérifie le taux, le plafond, les conditions de retrait et les garanties du livret précis. Ce n’est pas un compte de titres.']];
function envelopes(){return `<div class="card" style="margin-bottom:22px"><h2 class="section-title">L’enveloppe est le contenant. Le produit est ce que tu mets dedans.</h2><div class="envelope-line"><b>PEA · Enveloppe</b>→<b>ETF · Type de fonds</b>→<b>ETF Monde éligible · Produit</b></div><p class="subtitle">Un ETF peut investir dans des actions ou des obligations. Son indice et son éligibilité varient d’un produit à l’autre.</p><div class="notice">${state.profile.residence==='nc'?'Nouvelle-Calédonie : la devise XPF ne détermine pas la résidence fiscale. Les dispositifs métropolitains ne sont pas automatiquement accessibles. Fais vérifier ton éligibilité et le traitement fiscal local.':'Les règles dépendent de ta résidence fiscale et du produit. Vérifie les conditions officielles avant d’ouvrir une enveloppe.'}</div></div><div class="viewgrid">${envs.map((e,i)=>`<div class="card">${icon('building')}<h3>${e[0]}</h3><p>${e[1]}</p><button class="textbutton" data-env="${i}">Comprendre cette enveloppe →</button></div>`).join('')}</div>`}
const lessons=curriculum.map(l=>[l.title,l.category,l.subtitle,l.body.join(' ')]);
const learningCategories=['Les bases avant d’investir','Les catégories de produits','Enveloppes et plateformes','Passer à l’action','Pour aller plus loin'];
state.quizPassed=Array.isArray(state.quizPassed)?[...new Set(state.quizPassed.filter(i=>Number.isInteger(i)&&curriculum[i]))]:[];
function lessonPassed(i){return state.quizPassed.includes(i)}

function learn(){return heading('Un peu plus clair, chaque jour.','Cinq rubriques pour avancer, des exemples concrets et trois questions par leçon.')+`<section class="card learning-overview"><div><span class="tiny-label">MON APPRENTISSAGE</span><h2>${state.quizPassed.length} / ${lessons.length} leçons validées</h2><p>Chaque QCM réussi fait avancer ton parcours. Les leçons de l’ancien programme restent repérées.</p></div><div class="ring" style="--progress:${Math.round(state.quizPassed.length/lessons.length*100)}%"><span>${Math.round(state.quizPassed.length/lessons.length*100)}%</span></div></section><nav class="learning-nav" aria-label="Rubriques d’apprentissage">${learningCategories.map((cat,i)=>`<button class="chip" data-learning-category="${i}">${i+1}. ${cat}</button>`).join('')}</nav>${learningCategories.map((cat,c)=>{const ids=curriculum.flatMap((l,i)=>l.category===cat?[i]:[]);return `<section id="learning-category-${c}" class="learning-category" tabindex="-1"><div class="learning-section-heading"><div><span class="tiny-label">RUBRIQUE ${c+1}</span><h2>${cat}</h2></div><span class="pill">${ids.filter(lessonPassed).length} / ${ids.length} validées</span></div><div class="viewgrid">${ids.map(i=>{const l=curriculum[i];return `<button class="card lesson-card" data-lesson="${i}"><div class="cardtop"><span class="asset-icon">${icon(c===4?'invest':'book')}</span><span class="overline">${lessonPassed(i)?'✓ Validée':state.lessons.includes(i)?'Déjà étudiée · QCM à compléter':'4–6 min · QCM'}</span></div><h3>${l.title}</h3><p>${l.subtitle}</p>${l.nc?'<span class="nc-tag">Repère fiscal NC</span>':''}<span class="textbutton">${lessonPassed(i)?'Revoir':'Ouvrir'} la leçon →</span></button>`}).join('')}</div></section>`}).join('')}`}

function sim(){return heading('Le temps fait une différence.','Explore des hypothèses et construis un objectif qui te ressemble.')+`<div class="sim-grid"><form id="simform" class="card"><h2 class="section-title">Tes hypothèses</h2>${goalSelector()}${[['capital','Dernière valeur connue'],['monthly','Versement mensuel à venir'],['target','Mon objectif']].map(([name,label])=>`<label class="field">${label} (${unit()})${moneyInput(name,state[name],name==='capital')}</label>`).join('')}${[['years','Horizon total depuis le départ (années)',state.years,1,50,1],['rate','Rendement annuel hypothétique (%)',state.rate,-20,20,.1]].map(([id,l,v,min,max,step])=>`<label class="field">${l}<input name="${id}" type="number" value="${v}" min="${min}" max="${max}" step="${step}" required></label>`).join('')}<button class="btn" type="submit">Enregistrer mon objectif →</button><p class="source currency-source">Conversion à parité fixe :<br>1 000 XPF = 8,38 € · <a href="https://www.ieom.fr/" target="_blank" rel="noopener">IEOM ↗</a></p></form><div class="card" id="simresult">${simResult()}</div></div>`}
function simResult(vals=state){const g={...activeGoal(),monthly:vals.monthly,rate:vals.rate,years:vals.years,target:vals.target};const t=goalTimeline(g);return `<h2 class="section-title">Une vision de ton futur</h2><div class="statbox" style="margin-top:24px"><span class="overline">${t.expired?'Dernière valeur connue':'Capital projeté au '+dateLabel(t.deadline)}</span><div class="amount">${amount(t.end.value)} <small>${unit()}</small></div></div>${chart(g.capital,g.monthly,g.rate,g.years,g.target)}${historyPanel(activeGoal())}<div class="metric-row"><div><small>Départ + versements enregistrés</small><b>${amount(t.paidActual)} ${unit()}</b></div><div><small>Départ + versements à l’horizon</small><b>${amount(t.end.paid)} ${unit()}</b></div></div><div class="notice ${t.hit?'goal-notice':''}">${t.hit?`<span class="goal-dot" aria-hidden="true"></span><span>${t.hit.actual?'Objectif atteint selon le relevé du':'Objectif projeté au'} <b>${dateLabel(t.hit.date)}</b>.</span>`:t.expired?'L’horizon choisi est passé. Tu peux prolonger la durée pour afficher une nouvelle projection.':'Avec ces hypothèses, l’objectif ne serait pas atteint sur cette durée.'}</div>${goalInfo()}`}
function selectField(name,label,opts){return `<label class="field">${label}<select name="${name}">${opts.map(([v,l])=>`<option value="${v}" ${state.profile[name]==v?'selected':''}>${l}</option>`).join('')}</select></label>`}
function profile(){const p=state.profile;return heading('Un investissement qui te ressemble.','Tes objectifs, ton rythme, tes limites : commençons par toi.')+`<form class="card wide" id="profileform"><div class="cardtop"><h2 class="section-title">Mon profil investisseur</h2><span class="pill">8 repères + ta situation</span></div><div class="formgrid">${selectField('goal','Quel est ton objectif ?',[['Faire grandir mon patrimoine','Faire grandir mon patrimoine'],['Préparer ma retraite','Préparer ma retraite'],['Financer un projet','Financer un projet'],['Créer des revenus complémentaires','Créer des revenus complémentaires']])}<label class="field">Dans combien d’années utiliseras-tu cet argent ?<input name="horizon" type="number" min="1" max="50" required value="${p.horizon}"></label><label class="field">Capacité d’épargne mensuelle (${unit()})${moneyInput('monthly',state.monthly)}</label>${selectField('liquidity','Quand dois-tu pouvoir récupérer cet argent ?',[['court','À tout moment pour mes dépenses'],['moyen','Dans quelques années'],['long','Pas avant mon objectif à long terme']])}<label class="field">Tolérance émotionnelle au risque : <output>${p.risk}</output>/10<input name="risk" type="range" min="1" max="10" value="${p.risk}"><small>1 : les baisses m’inquiètent · 10 : je tolère de fortes baisses</small></label><label class="field">Capacité financière à supporter une perte : <output>${p.loss}</output>/10<input name="loss" type="range" min="1" max="10" value="${p.loss}"><small>1 : aucun coussin financier · 10 : sans compromettre mes besoins</small></label>${selectField('knowledge','Tes connaissances',[['debutant','Je débute'],['intermediaire','Je connais les bases'],['avance','Je connais les mécanismes et les risques']])}${selectField('experience','Ton expérience',[['aucune','Je n’ai jamais investi'],['fonds','J’ai déjà investi dans des fonds'],['marche','Je connais les marchés']])}${selectField('involvement','Le temps que tu souhaites y consacrer',[['passif','Un suivi occasionnel'],['actif','Un suivi régulier et des recherches']])}${selectField('safety','As-tu une réserve pour les imprévus ?',[['non','Pas encore'],['oui','Oui, distincte de mon argent à investir']])}${selectField('residence','Ta résidence fiscale',[['nc','Nouvelle-Calédonie'],['fr','France métropolitaine'],['autre','Autre / à vérifier']])}</div><div class="notice">Le profil est un repère éducatif. Le score retient la plus faible de ta tolérance au risque et de ta capacité de perte. Un besoin d’argent proche réduit la compatibilité des actifs risqués.</div><div class="form-actions"><span class="overline">Tes réponses sont conservées sur ce navigateur.</span><button class="btn" type="submit">Découvrir mon profil →</button></div></form>`}
function applyPalette(palette){const chosen=['green','blue','red'].includes(palette)?palette:'green';document.documentElement.dataset.palette=chosen;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',{green:'#07382c',blue:'#071b38',red:'#38070b'}[chosen]);}
function render(){accountChrome();if(!cloud.ready){$('#main').innerHTML=cloudLanding();return;}applyPalette(state.palette);const historyWasOpen=$('details.history-panel')?.open;$('#currency-select').value=state.currency==='EUR'?'EUR':'XPF';current=location.hash.slice(1)||'accueil';if(!nav.some(x=>x[0]===current))current='accueil';$('#nav').innerHTML=nav.map(([id,n,ic])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(ic)}<span>${n}</span></a>`).join('');$('#breadcrumb').innerHTML=`Mon espace <span>/</span> ${nav.find(x=>x[0]===current)[1]}`;$('#sideprogress').textContent=`${completedStages()} grandes étapes sur 5 · ${progress()} %`;$('.mini-progress span').style.width=progress()+'%';$('#main').innerHTML=!activeGoal()&&['accueil','objectifs','simulateurs'].includes(current)?emptyGoals()+(current==='accueil'?dashboardBudget():''):({accueil:dashboard,objectifs:objectives,budget,plan,investir:invest,apprendre:learn,simulateurs:sim,profil:profile}[current])();if(historyWasOpen&&$('details.history-panel'))$('details.history-panel').open=true;document.title=`${nav.find(x=>x[0]===current)[1]} · Cap`;}
function go(s){if(location.hash==='#'+s)render();else location.hash=s;window.scrollTo(0,0)}function modal(html){$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function openAsset(i){const a=assets[i],s=scores(a);modal(`<span class="asset-icon" style="background:${a.bg};color:${a.color}">${icon(a.icon)}</span><h2 class="modal-title">${a.name}</h2><p class="modal-text">${a.desc}</p><div class="detailstats"><div>Compatibilité<b>${s.total}/100</b></div><div>Variations de valeur<b>${a.vol}</b></div><div>Complexité<b>${a.difficulty}</b></div></div><h3 class="section-title">Pourquoi ce score ?</h3>${s.items.map(([n,v,w])=>`<div class="explanation"><span>${n} <small>· poids ${w} %</small></span><b>${Math.round(v)}/100</b></div>`).join('')}<p class="source">La complexité tient aussi compte de ton expérience et du temps de suivi souhaité. Moyenne pondérée, avec plafonds pour besoin de liquidité proche, horizon court, crypto pour débutant et levier. Échelle interne non validée comme conseil financier.</p><div class="modal-text"><h3>Comment ça fonctionne</h3><p>${a.works}</p><h3>Ce qu’il faut peser</h3><p><b>Atouts :</b> ${a.pros}</p><p><b>Risques et limites :</b> ${a.cons}</p><h3>Horizon et disponibilité</h3><p>Repère utilisé pour le score : ${a.horizon} ans${a.complexity===5?' (le levier n’est pas une stratégie d’épargne proposée)':''}. Ce repère n’est pas une garantie. ${a.liquid>=.8?'Négociation généralement possible sur le marché, sans garantie de prix ni d’exécution.':'Revente potentiellement longue et dépendante des acheteurs.'}</p><h3>Où le détenir ?</h3><p>${a.envelopes}</p><h3>Rendement historique</h3><p>Aucun rendement unique pour cette catégorie : il dépend du produit, de la période, des frais et de la devise. Consulte le document d’informations clés du produit précis. Les performances passées ne préjugent pas des performances futures.</p><a href="https://www.amf-france.org/fr/espace-epargnants/savoir-bien-investir/cadrer-son-projet/risques-et-rendements-des-placements" target="_blank" rel="noopener">Approfondir avec l’AMF ↗</a></div><button class="btn sectiongap" data-action="toenvelopes">Comprendre les enveloppes →</button>`)}
function openLesson(i){const l=curriculum[i];if(!l)return;modal(`<article class="lesson-content"><span class="tiny-label">${l.category.toUpperCase()} · 4–6 MINUTES</span><h2 class="modal-title">${l.title}</h2><p class="lesson-lead">${l.subtitle}</p>${l.risk?`<div class="lesson-risk"><strong>Repère de risque</strong><span>${l.risk}</span><small>Indication pédagogique générale, distincte de l’indicateur réglementaire du produit.</small></div>`:''}${l.body.map((text,j)=>`<section class="lesson-paragraph"><span>${String(j+1).padStart(2,'0')}</span><p>${lessonText(escapeHTML(text))}</p></section>`).join('')}${l.nc?`<aside class="nc-note"><strong>ⓘ Résidence fiscale en Nouvelle-Calédonie</strong><p>${escapeHTML(l.nc)}</p><small>Repères vérifiés le 7 septembre 2026 · À confirmer pour ta situation et ton contrat.</small></aside>`:''}<div class="lesson-sources"><strong>Sources et approfondissement</strong>${l.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener">${title} ↗</a>`).join('')}</div><form class="lesson-quiz" data-lesson-quiz="${i}"><div class="quiz-heading"><span class="quiz-emblem">✓</span><div><span class="tiny-label">À TOI DE JOUER</span><h3>As-tu retenu l’essentiel ?</h3><p>3 questions · Une seule réponse par question</p></div></div>${l.questions.map((q,k)=>`<fieldset><legend><span>${k+1} / 3</span> ${lessonText(escapeHTML(q.prompt))}</legend>${q.options.map((o,j)=>`<label class="quiz-choice"><input type="radio" required name="q${k}" value="${j}"><span>${lessonText(escapeHTML(o))}</span></label>`).join('')}<div class="question-feedback" id="question-feedback-${k}"></div></fieldset>`).join('')}<button class="btn" type="submit">Vérifier mes réponses</button><div class="quiz-result" role="status" aria-live="polite"></div></form></article>`);$('#modalbody').scrollTop=0;}
function gradeLesson(i,answers){const l=curriculum[i];return l.questions.map((q,k)=>answers[k]===q.answer)}
function validateLessonQuiz(form){const i=Number(form.dataset.lessonQuiz),l=curriculum[i];if(!l)return;const answers=l.questions.map((_,k)=>{const v=form.elements.namedItem('q'+k).value;return v===''?null:Number(v)});if(answers.includes(null)){form.reportValidity();return;}const correct=gradeLesson(i,answers),score=correct.filter(Boolean).length;form.querySelectorAll('fieldset').forEach((field,k)=>{field.querySelectorAll('.quiz-choice').forEach((choice,j)=>{choice.classList.toggle('answer-correct',j===l.questions[k].answer);choice.classList.toggle('answer-wrong',j===answers[k]&&!correct[k]);});field.querySelector('.question-feedback').innerHTML=`<p class="${correct[k]?'quiz-good':'quiz-retry'}"><strong>${correct[k]?'✓ Bonne réponse':'À revoir'}</strong> · ${lessonText(escapeHTML(l.questions[k].explanation))}</p>`;});form.querySelector('.quiz-result').textContent=score===3?'3 / 3 · Leçon validée ! Tu peux passer à la suivante.':`${score} / 3 · Relis les corrections et ajuste tes réponses pour valider la leçon.`;if(score===3){if(!lessonPassed(i))state.quizPassed.push(i);if(!state.lessons.includes(i))state.lessons.push(i);if(i===4)markPlanItem('asset-etf');if(i===2)markPlanItem('profile-loss');if(i===7)markPlanItem('envelope-distinction');save();render();}form.querySelector('.quiz-result').scrollIntoView({block:'nearest',behavior:'smooth'});}
document.addEventListener('submit',e=>{if(e.target.matches('form[data-lesson-quiz]')){e.preventDefault();validateLessonQuiz(e.target);}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-learning-category]');if(button){const section=document.getElementById('learning-category-'+button.dataset.learningCategory);section?.scrollIntoView({behavior:'smooth',block:'start'});section?.focus({preventScroll:true});}});

function openStep(i){const dest=steps[i][2];if(nav.some(n=>n[0]===dest)){go(dest);return}if(dest.startsWith('lesson:')){openLesson(+dest.split(':')[1]);return}if(dest==='enveloppes'){filter='Les enveloppes';go('investir');return}const texts={safety:'Liste tes dépenses essentielles mensuelles. Choisis une réserve adaptée à la stabilité de tes revenus, à tes charges et à tes proches. Garde-la sur un support disponible et dont tu comprends la garantie. Cette réserve n’est pas le capital destiné aux marchés.',broker:'Compare les frais de courtage, les frais de change et la tenue de compte. Vérifie les autorisations de l’intermédiaire auprès du régulateur compétent, son accessibilité depuis ta résidence et la protection des fonds. Ne te fie pas seulement aux publicités.',allocation:'Sépare l’épargne disponible, les projets proches et les objectifs lointains. Pour chaque poche, choisis un niveau de risque supportable. Regarde les recoupements : deux ETF différents peuvent détenir les mêmes entreprises. Une allocation chiffrée nécessite une analyse plus complète de ta situation.',first:'Avant de confirmer : vérifie l’identifiant du produit, lis son document d’informations clés, compare les frais, contrôle la quantité et le type d’ordre. Prévois ce que tu feras en cas de baisse. Cette application n’exécute aucune transaction.',regular:'Définis un versement compatible avec ton budget, après les dépenses et l’épargne de sécurité. Fixe une date de suivi périodique. Revois ton plan lors d’un changement de revenus, de famille ou d’objectif, plutôt qu’en réaction à chaque variation de marché.'};modal(`<span class="tiny-label">MON PLAN · POUR ALLER PLUS LOIN</span><h2 class="modal-title">${steps[i][0]}</h2><p class="modal-text">${texts[dest]}</p>${dest==='broker'?'<a class="textbutton" target="_blank" rel="noopener" href="https://www.amf-france.org/fr/espace-epargnants/proteger-son-epargne/faire-les-verifications">Vérifier une autorisation avec l’AMF ↗</a>':''}<div class="form-actions"><button class="btn" data-complete="${i}">${state.done.includes(i)?'Étape déjà terminée ✓':'Marquer cette étape comme terminée ✓'}</button></div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-go]');if(!el)return;if(el.classList.contains('close')){$('#modal').close();return}const d=el.dataset;if(d.planResource){openPlanResource(d.planResource);return;}if(d.action==='addrecord'){if(!activeGoal().startDateConfirmed){openGoalForm(activeGoal());toast('Précise la date de départ de cet objectif avant ton premier relevé.');}else openRecordForm();return;}if(d.recordId){openRecordForm(d.recordId);return;}if(d.goalId){selectGoal(d.goalId);const choice=[...document.querySelectorAll('[data-goal-id]')].find(button=>button.dataset.goalId===d.goalId);choice?.focus({preventScroll:true});return;}if(d.action==='newgoal'){openGoalForm();return;}if(d.action==='editgoal'){openGoalForm(activeGoal());return;}if(d.action==='cancelgoal'){$('#modal').close();return;}if(d.go)go(d.go);if(d.asset!==undefined)openAsset(+d.asset);if(d.lesson!==undefined)openLesson(+d.lesson);if(d.stepopen!==undefined)openStep(+d.stepopen);if(d.filter){filter=d.filter;render()}if(d.env!==undefined){const v=envs[+d.env];modal(`<span class="tiny-label">LES ENVELOPPES</span><h2 class="modal-title">${v[0]}</h2><p class="modal-text">${v[1]}</p><p class="modal-text">${v[2]}</p><div class="notice">Les conditions d’accès, frais et règles fiscales sont à vérifier pour ta résidence. L’enveloppe ne détermine pas à elle seule le risque : celui-ci dépend des supports détenus.</div>`)}if(d.action==='toenvelopes'){$('#modal').close();filter='Les enveloppes';go('investir')}if(d.action==='customize')modal(`<h2 class="modal-title">Un accueil à ton image</h2><p class="modal-text">Choisis ta palette et les informations à afficher.</p><fieldset class="palette-fieldset"><legend>Palette de couleurs</legend><div class="palette-options">${[['green','Vert','#17634b'],['blue','Bleu','#174f8e'],['red','Rouge','#8e1721']].map(([id,label,color])=>`<label class="palette-option"><input type="radio" name="palette" value="${id}" ${(!state.palette&&id==='green')||state.palette===id?'checked':''}><span class="palette-preview"><span style="background:${color}"></span><span style="background:#fff"></span><span style="background:#000"></span></span><b>${label}</b><span class="palette-option-check" aria-hidden="true">✓</span></label>`).join('')}</div></fieldset><label class="roadstep"><input type="checkbox" id="showprofile" ${!state.hideProfile?'checked':''}> Afficher la carte de mon profil</label><div class="form-actions"><button class="light" data-action="cancelpalette">Annuler</button><button class="btn" data-action="savecustom">Enregistrer</button></div>`);if(d.action==='cancelpalette'){$('#modal').close();}if(d.action==='savecustom'){state.hideProfile=!$('#showprofile').checked;state.palette=$('input[name="palette"]:checked')?.value||'green';save();$('#modal').close();render()}
if(d.complete!==undefined){const i=+d.complete;if(!state.done.includes(i))state.done.push(i);if(legacyPlanMap[i])markPlanItem(legacyPlanMap[i]);if(i===2)state.profile.safety='oui';save();$('#modal').close();render();toast('Une étape de plus. Bien joué !')}});
document.addEventListener('change',e=>{if(e.target.dataset.planItem){const id=e.target.dataset.planItem,openPanels=[...document.querySelectorAll('.plan-stage[open],.plan-substep[open]')].map(panel=>panel.id);markPlanItem(id,e.target.checked);save();render();document.querySelectorAll('.plan-stage,.plan-substep').forEach(panel=>panel.open=openPanels.includes(panel.id));document.querySelector('[data-plan-item="'+id+'"]')?.focus({preventScroll:true});return;}if(e.target.name==='palette'){applyPalette(e.target.value);return;}if(e.target.hasAttribute('data-goal-selector')){selectGoal(e.target.value);return;}if(e.target.id==='currency-select'){changeCurrency(e.target.value);return;}if(e.target.dataset.step!==undefined){const i=+e.target.dataset.step;state.done=e.target.checked?[...new Set([...state.done,i])]:state.done.filter(x=>x!==i);if(i===2)state.profile.safety=e.target.checked?'oui':'non';save();render()}});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-money'))validateMoneyInput(e.target);if(e.target.type==='range')e.target.parentElement.querySelector('output').textContent=e.target.value;if(e.target.closest('#simform')){const f=$('#simform');if(f.checkValidity()){const vals=simValues(f);$('#simresult').innerHTML=simResult(vals)}}});
document.addEventListener('submit',e=>{e.preventDefault();if(!validateMoneyFields(e.target)){e.target.reportValidity();return;}if(e.target.id==='recordform'){submitRecordForm(e.target);return;}if(e.target.id==='goalform'){submitGoalForm(e.target);return;}if(e.target.id==='profileform'){const d=Object.fromEntries(new FormData(e.target));state.monthly=readMoneyInput(e.target.elements.namedItem('monthly'));delete d.monthly;['horizon','risk','loss'].forEach(k=>d[k]=Number(d[k]));state.profile=d;state.done=[...new Set([...state.done,0,1])];markPlanItem('profile-questionnaire');save();go('accueil');toast('Ton profil et tes compatibilités ont été mis à jour.')}if(e.target.id==='simform'){Object.assign(state,simValues(e.target));save();toast('Ton objectif a été enregistré.');render()}});

function objectives(){
 const g=activeGoal();
 return heading('À chaque projet, son objectif.','Organise tes projets et avance avec un plan d’épargne pour chacun.',goalCreateButton())+`<div class="objectives-layout"><aside class="card objectives-list"><div class="cardtop"><h2>Mes objectifs</h2><span class="pill">${state.goals.length} projet${state.goals.length>1?'s':''}</span></div>${goalSelector()}<div class="goal-list">${state.goals.map(item=>`<button class="goal-item ${goalAchieved(item)?'goal-achieved':''} ${g.id===item.id?'selected':''}" data-goal-id="${escapeHTML(item.id)}" aria-pressed="${g.id===item.id}"><span class="asset-icon">${icon(goalType(item)[2])}</span><span class="goal-item-content"><b>${goalNameWithStatus(item)}</b><span>${amount(item.target)} ${unit()}</span><progress class="goal-progress" value="${fundedPercent(item)}" max="100" aria-label="Épargne constituée"></progress><small>${goalAchieved(item)?'Objectif atteint · ':''}${fundedPercent(item).toLocaleString('fr-FR',{maximumFractionDigits:1})} % constitué · ${item.years} ans</small></span></button>`).join('')}</div><p class="card-note">Chaque projet a son propre capital et ses versements. Répartis ton épargne entre tes objectifs sans compter deux fois la même somme.</p></aside><section class="card goal-detail" aria-label="Détails de l’objectif sélectionné"><div class="cardtop"><div><span class="overline">${escapeHTML(goalType(g)[1])}</span><h2 class="goal-detail-title">${escapeHTML(g.name)}</h2></div><button class="textbutton" data-action="editgoal">Modifier ${icon('settings')}</button></div><div class="goal-head"><div><span class="overline">Capital actuel / objectif</span>${goalAmount(g)}</div><span class="pill">${g.capital>=g.target?'Objectif constitué':'En cours'}</span></div>${goalProgress(g)}<div class="metric-row goal-metrics"><div><small>Reste à épargner</small><b>${amount(Math.max(0,g.target-g.capital))} ${unit()}</b></div><div><small>Versement mensuel prévu</small><b>${amount(g.monthly)} ${unit()}</b></div><div><small>Horizon</small><b>${g.years} ans</b></div></div>${chart(g.capital,g.monthly,g.rate,g.years,g.target)}${historyPanel(g)}${goalSavingsPlan(g)}${goalInfo()}</section></div>`;
}
function goalSavingsPlan(g){const t=goalTimeline(g);return `<div class="savings-plan"><h3>Mon plan d’épargne</h3><div class="savings-plan-row"><span class="check-circle">1</span><p><b>${amount(g.capital)} ${unit()} de portefeuille</b><small>Valeur renseignée au ${dateLabel(t.last.date)}.</small></p><button class="textbutton" data-action="addrecord">Actualiser</button></div><div class="savings-plan-row"><span class="check-circle">2</span><p><b>${amount(g.monthly)} ${unit()} par mois à venir</b></p><button class="textbutton" data-action="editgoal">Ajuster</button></div><div class="savings-plan-row"><span class="check-circle">3</span><p><b>${t.hit?(t.hit.actual?'Objectif atteint le ':'Objectif projeté le ')+dateLabel(t.hit.date):t.expired?'Horizon terminé : ajuste ta durée':'Objectif non atteint sur cette durée'}</b><small>${amount(t.end.value)} ${unit()} ${t.expired?'dans ton dernier relevé':'projetés au '+dateLabel(t.deadline)}.</small></p></div></div>`}
function openGoalForm(goal=null){
 const g=goal||{type:'home',name:'',capital:0,initialCapital:0,startDate:todayISO(),records:[],monthly:0,target:0,years:10,rate:0};
 modal(`<span class="tiny-label">MES OBJECTIFS · ${unit()}</span><h2 class="modal-title">${goal?'Modifier cet objectif':'Créer un nouvel objectif'}</h2><form id="goalform" data-edit-id="${goal?escapeHTML(goal.id):''}">
 <fieldset class="goal-form-section"><legend><span>1</span> Ton projet</legend><div class="formgrid"><label class="field">Catégorie<select name="type">${goalTypes.map(([id,label])=>`<option value="${id}" ${g.type===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Nom de l’objectif <input name="name" maxlength="80" value="${escapeHTML(g.name)}" placeholder="Ex. Notre première maison"><small>Facultatif : la catégorie sera utilisée par défaut.</small></label><label class="field goal-field-full">Montant à atteindre (${unit()})${moneyInput('target',g.target)}</label></div></fieldset>
 <fieldset class="goal-form-section"><legend><span>2</span> Ton point de départ</legend><div class="formgrid"><label class="field">Date de début<input name="startDate" type="date" value="${g.startDate}" max="${g.records.length?sortedRecords(g)[0].date:todayISO()}" required><small>Au plus tard ${g.records.length?'à la date du premier relevé':'aujourd’hui'}.</small></label><label class="field">Capital initial (${unit()})${moneyInput('capital',g.initialCapital,g.records.length>0)}<small>${g.records.length?'Conservé pour préserver ton historique.':'La somme déjà affectée au projet à cette date.'}</small></label></div></fieldset>
 <fieldset class="goal-form-section"><legend><span>3</span> Tes prévisions</legend><div class="formgrid"><label class="field goal-field-full">Versement mensuel à venir (${unit()})${moneyInput('monthly',g.monthly)}<small>Tu peux l’ajuster sans modifier les versements déjà enregistrés.</small></label><label class="field">Durée totale (années)<input name="years" type="number" min="1" max="50" step="1" value="${g.years}" required><small>À compter de la date de début.</small></label><label class="field">Rendement annuel estimé (%)<input name="rate" type="number" min="-20" max="20" step="0.1" value="${g.rate}" required><small>Hypothèse non garantie. 0 % pour compter uniquement les versements.</small></label></div></fieldset>
 <div class="form-actions goal-edit-actions"><button type="button" class="light" data-action="cancelgoal">Annuler</button><button class="btn create-goal" type="submit">${goal?'Enregistrer les modifications':'Créer mon objectif'}</button></div>
 ${goal?`<div class="goal-delete-area"><button type="button" class="goal-delete-link" data-action="requestdeletegoal" aria-expanded="false" aria-controls="goal-delete-confirm">Supprimer l’objectif</button><div id="goal-delete-confirm" class="goal-delete-confirm" hidden><strong>Supprimer « ${escapeHTML(g.name)} » ?</strong><p>Cet objectif et ses ${g.records.length} relevé${g.records.length>1?'s':''} seront supprimés définitivement.</p><div><button type="button" class="light" data-action="canceldeletegoal">Conserver l’objectif</button><button type="button" class="goal-delete-button" data-delete-goal="${escapeHTML(g.id)}">Confirmer la suppression</button></div></div></div>`:''}</form>`);

}
function emptyGoals(){return heading('Un nouveau projet commence ici.','Crée un objectif pour visualiser ta progression et préparer tes prochains versements.')+`<section class="card empty-goals"><span class="asset-icon">${icon('plan')}</span><h2>Aucun objectif pour le moment</h2><p>Un achat, un voyage, une réserve de sécurité… donne une direction à ton épargne.</p>${goalCreateButton()}</section>`;}
function deleteGoal(id){const index=state.goals.findIndex(g=>g.id===id);if(index<0)return false;syncActiveGoal();state.goals.splice(index,1);if(state.activeGoalId===id){state.activeGoalId=state.goals[Math.min(index,state.goals.length-1)]?.id||null;loadActiveGoal();}save();return true;}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const action=button.dataset.action;if(action==='requestdeletegoal'){$('#goal-delete-confirm').hidden=false;button.setAttribute('aria-expanded','true');$('#goal-delete-confirm [data-action="canceldeletegoal"]').focus();}if(action==='canceldeletegoal'){$('#goal-delete-confirm').hidden=true;const trigger=$('[data-action="requestdeletegoal"]');trigger.setAttribute('aria-expanded','false');trigger.focus();}if(button.dataset.deleteGoal&&deleteGoal(button.dataset.deleteGoal)){$('#modal').close();go('objectifs');toast('Objectif supprimé.');}});
function storeGoal(values,id=''){
 if(!goalTypes.some(t=>t[0]===values.type))throw Error('Type d’objectif invalide.');
 const name=String(values.name||'').trim().slice(0,80)||goalTypes.find(t=>t[0]===values.type)[1];
 const numbers=Object.fromEntries(goalKeys.map(k=>[k,Number(values[k])]));
 if(Object.values(numbers).some(v=>!Number.isFinite(v))||numbers.target<=0||numbers.target>1e11||numbers.capital<0||numbers.capital>1e11||numbers.monthly<0||numbers.monthly>1e8||!Number.isInteger(numbers.years)||numbers.years<1||numbers.years>50||numbers.rate< -20||numbers.rate>20)throw Error('Vérifie les montants et la durée de ton objectif.');
 syncActiveGoal();
 let g=id?state.goals.find(g=>g.id===id):null;
 if(id&&!g)throw Error('Cet objectif est introuvable.');
 const startDate=values.startDate||g?.startDate||todayISO();
 if(!isISODate(startDate)||startDate>todayISO())throw Error('Choisis une date de début valide, au plus tard aujourd’hui.');
 if(g?.records.length&&(startDate>sortedRecords(g)[0].date||numbers.capital!==g.initialCapital))throw Error('La date de départ doit précéder le premier relevé. Le capital initial reste conservé avec ton historique.');
 if(g)Object.assign(g,{name,type:values.type,...numbers,startDate,initialCapital:numbers.capital});else{g={id:crypto.randomUUID(),name,type:values.type,...numbers,startDate,initialCapital:numbers.capital,records:[]};state.goals.push(g);}
 g.startDateConfirmed=true;g.capital=latestObservation(g).value;
 state.activeGoalId=g.id;loadActiveGoal();['goal-purpose','goal-amount','goal-horizon'].forEach(id=>markPlanItem(id));save();return g;
}
function submitGoalForm(form){
 if(!form.checkValidity()){form.reportValidity();return;}
 const values=Object.fromEntries(new FormData(form));moneyKeys.forEach(k=>values[k]=readMoneyInput(form.elements.namedItem(k)));
 try{storeGoal(values,form.dataset.editId);$('#modal').close();go('objectifs');toast(form.dataset.editId?'Objectif mis à jour.':'Ton nouvel objectif est créé.');}catch(error){toast(error.message);}
}

function goalInfo(){return `<div class="goal-info-footer"><span class="info-help"><button class="info-trigger" type="button" aria-label="Informations sur l’historique et la projection" aria-describedby="goal-info-tooltip"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6"/><circle cx="12" cy="7.5" r=".7" class="info-dot"/></svg></button><span class="info-tooltip" id="goal-info-tooltip" role="tooltip"><strong>À propos de ce suivi</strong><span>Un relevé par mois : le versement réalisé et la valeur totale du portefeuille, gains ou pertes compris. « Total Versements » exclut le capital initial.</span><span>La progression utilise la dernière valeur saisie. Modifier les prévisions ne change pas l’historique ; « Corriger » permet de rectifier un relevé. Les mois sans saisie ne sont pas reconstitués.</span><span>La projection repart de la dernière valeur connue, à partir d’aujourd’hui, avec les versements futurs et un rendement hypothétique constant. Elle exclut frais, fiscalité et inflation. Aucun rendement n’est garanti.</span><span>Les données sont conservées sur ce navigateur.</span></span></span></div>`}
function historyPanel(g){const records=sortedRecords(g),total=records.reduce((n,r)=>n+r.investment,0);return `<details class="history-panel"><summary><span>${icon('plan')} Historique et versements <small>${records.length} relevé${records.length>1?'s':''}</small></span><span class="history-chevron" aria-hidden="true">⌄</span></summary><div class="history-content"><div class="history-head"><p class="history-start-date">${g.startDateConfirmed?'Début le <b>'+dateLabel(g.startDate)+'</b>':'<b>Date de départ à préciser</b>'}</p><button class="btn" data-action="addrecord">＋ Ajouter un relevé</button></div><div class="history-table-wrap" tabindex="0" role="region" aria-label="Historique des versements et valeurs du portefeuille"><table class="history-table"><caption class="sr-only">Historique de ${escapeHTML(g.name)}</caption><thead><tr><th scope="col">Date</th><th scope="col">Versement réalisé (${unit()})</th><th scope="col">Valeur du portefeuille (${unit()})</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr class="baseline-row"><th scope="row">${dateLabel(g.startDate)}<small>Point de départ</small></th><td>—</td><td>${amount(g.initialCapital)}</td><td></td></tr>${records.map(r=>`<tr><th scope="row">${dateLabel(r.date)}</th><td>${amount(r.investment)}</td><td>${amount(r.value)}</td><td><button class="textbutton" data-record-id="${escapeHTML(r.id)}" aria-label="Corriger le relevé du ${dateLabel(r.date)}">Corriger</button></td></tr>`).join('')}</tbody></table></div>${records.length?'':'<p class="history-empty">Ton historique commence ici. Ajoute ton premier relevé pour suivre tes progrès réels.</p>'}<div class="history-totals"><span>Total Versements <b>${amount(total)} ${unit()}</b></span><span>Capital initial <b>${amount(g.initialCapital)} ${unit()}</b></span></div></div></details>`}
function openRecordForm(id=''){
 const g=activeGoal(),record=id?g.records.find(r=>r.id===id):null;
 if(id&&!record){toast('Relevé introuvable.');return;}
 const r=record||{date:todayISO(),investment:0,value:0};
 modal(`<span class="tiny-label">${escapeHTML(g.name)} · ${unit()}</span><h2 class="modal-title">${record?'Corriger un relevé':'Ajouter un relevé mensuel'}</h2><form id="recordform" data-record-id="${escapeHTML(id)}"><div class="formgrid"><label class="field">Date du relevé<input name="date" type="date" value="${r.date}" min="${g.startDate}" max="${todayISO()}" required></label><label class="field">Montant investi durant ce mois (${unit()})${moneyInput('investment',r.investment)}<small>Versement réellement effectué, même s’il diffère de ton objectif mensuel.</small></label><label class="field">Valeur totale du portefeuille à cette date (${unit()})${moneyInput('value',r.value)}<small>Valeur après versement, gains ou pertes compris. Ce n’est pas le cumul de tes versements.</small></label></div><div class="notice">Ce relevé met à jour ton historique et la progression de ce projet. Le montant prévu pour les prochains mois reste inchangé.</div><div class="form-actions"><button type="button" class="light" data-action="cancelgoal">Annuler</button><button class="btn" type="submit">${record?'Enregistrer la correction':'Enregistrer le relevé'} →</button></div><p class="record-error" role="alert"></p></form>`);
 // Never suggest a portfolio value: require an explicit observation.
 if(!record){const input=$('#recordform').elements.namedItem('value');input.value='';}
}
function storeRecord(goal,values,id=''){
 const date=String(values.date),investment=Number(values.investment),value=Number(values.value);
 if(!isISODate(date)||date<goal.startDate||date>todayISO())throw Error('Le relevé doit être à la date de départ ou après celle-ci et ne pas être dans le futur.');
 if(!Number.isFinite(investment)||investment<0||investment>1e8||!Number.isFinite(value)||value<0||value>1e11)throw Error('Saisis des montants valides et positifs ou nuls.');
 if(goal.records.some(r=>r.id!==id&&r.date.slice(0,7)===date.slice(0,7)))throw Error('Un relevé existe déjà pour ce mois. Utilise « Corriger » sur cette ligne.');
 const entry=id?goal.records.find(r=>r.id===id):null;if(id&&!entry)throw Error('Relevé introuvable.');
 if(entry)Object.assign(entry,{date,investment,value});else goal.records.push({id:crypto.randomUUID(),date,investment,value});
 goal.records.sort((a,b)=>a.date.localeCompare(b.date));goal.capital=latestObservation(goal).value;
 if(goal.id===state.activeGoalId)loadActiveGoal();save();return goal;
}
function submitRecordForm(form){
 try{storeRecord(activeGoal(),{date:form.elements.namedItem('date').value,investment:readMoneyInput(form.elements.namedItem('investment')),value:readMoneyInput(form.elements.namedItem('value'))},form.dataset.recordId);$('#modal').close();render();if($('details.history-panel'))$('details.history-panel').open=true;toast('Relevé enregistré. Ton historique et ta projection sont à jour.');}
 catch(error){form.querySelector('.record-error').textContent=error.message;}
}
document.addEventListener('focusout',event=>{const input=event.target;if(input.hasAttribute('data-money')&&!input.readOnly&&validateMoneyInput(input)){const xpf=readMoneyInput(input);input.value=inputValue(xpf);input.dataset.xpf=xpf;input.dataset.displayed=input.value;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});window.addEventListener('hashchange',render);render();void startCloud();

// The information tooltip is also available by keyboard and touch focus.
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.info-help').forEach(el=>{if(el.matches(':hover')||el.contains(document.activeElement))el.classList.add('info-dismissed');});});
document.addEventListener('pointerout',event=>{const helper=event.target.closest?.('.info-help');if(helper&&!helper.contains(event.relatedTarget))helper.classList.remove('info-dismissed');});
document.addEventListener('focusout',event=>{const helper=event.target.closest?.('.info-help');if(helper&&!helper.contains(event.relatedTarget))helper.classList.remove('info-dismissed');});

const chartPointCache=new WeakMap();
function chartPoints(element){if(!chartPointCache.has(element))chartPointCache.set(element,JSON.parse(element.dataset.chartPoints));return chartPointCache.get(element)}
function nearestChartIndex(points,x){let selected=0,distance=Infinity;points.forEach((point,i)=>{const delta=Math.abs(point.x-x);if(delta<distance){distance=delta;selected=i;}});return selected;}
function showChartPoint(element,index){const points=chartPoints(element);index=Math.max(0,Math.min(index,points.length-1));const point=points[index];element.dataset.activePoint=index;
 const marker=element.querySelector('.chart-hover-marker');marker.style.display='';const line=marker.querySelector('line');line.setAttribute('x1',point.x);line.setAttribute('x2',point.x);marker.querySelectorAll('circle').forEach(circle=>{circle.setAttribute('cx',point.x);circle.setAttribute('cy',point.y)});
 const box=element.querySelector('.chart-readout');box.hidden=false;box.querySelector('.chart-readout-date').textContent=dateLabel(point.date);box.querySelector('.chart-readout-relative').textContent='('+relativeDate(point.date)+')';box.querySelector('.chart-readout-value').textContent=amount(point.value)+' '+unit();box.querySelector('.chart-readout-kind').textContent=point.current?(point.actual?'Situation actuelle · valeur renseignée':'Dernier relevé : '+dateLabel(point.observedDate)):point.actual?'Valeur renseignée':'Projection';
 const rect=element.getBoundingClientRect(),svg=element.querySelector('svg.chart'),screen=svg.createSVGPoint();screen.x=point.x;screen.y=point.y;const anchor=screen.matrixTransform(svg.getScreenCTM());
 const left=Math.max(8,Math.min(anchor.x-rect.left-box.offsetWidth/2,rect.width-box.offsetWidth-8));const top=Math.max(4,anchor.y-rect.top-box.offsetHeight-15);box.style.left=left+'px';box.style.top=top+'px';
}
function hideChartPoint(element){element.querySelector('.chart-readout').hidden=true;element.querySelector('.chart-hover-marker').style.display='none'}
document.addEventListener('pointermove',event=>{const element=event.target.closest?.('.interactive-chart');if(!element)return;const svg=element.querySelector('svg.chart'),point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());showChartPoint(element,nearestChartIndex(chartPoints(element),local.x));});
document.addEventListener('pointerdown',event=>{const element=event.target.closest?.('.interactive-chart');if(!element)return;const svg=element.querySelector('svg.chart'),point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());showChartPoint(element,nearestChartIndex(chartPoints(element),local.x));});
document.addEventListener('pointerout',event=>{const element=event.target.closest?.('.interactive-chart');if(element&&!element.contains(event.relatedTarget)&&event.pointerType!=='touch')hideChartPoint(element)});
document.addEventListener('focusin',event=>{if(event.target.matches?.('.interactive-chart'))showChartPoint(event.target,Number(event.target.dataset.activePoint||0))});
document.addEventListener('focusout',event=>{if(event.target.matches?.('.interactive-chart'))hideChartPoint(event.target)});
document.addEventListener('keydown',event=>{const element=event.target.closest?.('.interactive-chart');if(!element)return;let index=Number(element.dataset.activePoint||0);if(event.key==='Escape'){hideChartPoint(element);return;}if(event.key==='ArrowRight')index++;else if(event.key==='ArrowLeft')index--;else if(event.key==='Home')index=0;else if(event.key==='End')index=chartPoints(element).length-1;else return;event.preventDefault();showChartPoint(element,index);});

$('#modal').addEventListener('close',()=>applyPalette(state.palette));
